import { baseApi } from "@/redux/baseApi"
import type { ApiResponse } from "@/types/api"
import type { AiSuggestionState, RiskSuggestion } from "@/types/ai"

// aexa-frontend#922: AI-suggested-risk lifecycle -- dismiss, per-site
// dismissed history, previously-dismissed marking on re-analysis. Backed by
// aexa-server's /ai/suggestions/* routes (built against the same contract
// in parallel -- see PR description). RiskSuggestion.risk_id is
// regenerated by the AI every analysis run, so the server identifies a
// suggestion by a fingerprint of title+category instead; the frontend
// sends the full RiskSuggestion body and lets the server compute/store
// that fingerprint (see src/utils/aiSuggestionFingerprint.ts for the
// client-side mirror used to match fresh suggestions against dismissed
// rows without a round-trip per suggestion).
interface SuggestionActionBody {
  siteId: string
  suggestion: RiskSuggestion
}

const aiSuggestionsApi = baseApi.injectEndpoints({
  endpoints: (builder) => ({
    dismissSuggestion: builder.mutation<
      ApiResponse<AiSuggestionState>,
      SuggestionActionBody
    >({
      query: (body) => ({
        url: `/ai/suggestions/dismiss`,
        method: "POST",
        body,
      }),
      invalidatesTags: (_result, _error, { siteId }) => [
        { type: "AI_SUGGESTION_STATE", id: siteId },
      ],
    }),
    // Fire-and-forget after a successful import (see SitesEntities.tsx's
    // handleImportSuggestions) -- callers don't block the UI on this or
    // surface its errors beyond a console.warn.
    markSuggestionImported: builder.mutation<
      ApiResponse<AiSuggestionState>,
      SuggestionActionBody
    >({
      query: (body) => ({
        url: `/ai/suggestions/mark-imported`,
        method: "POST",
        body,
      }),
      invalidatesTags: (_result, _error, { siteId }) => [
        { type: "AI_SUGGESTION_STATE", id: siteId },
      ],
    }),
    // Returns every suggestion-state row (both DISMISSED and IMPORTED) for
    // a site, sorted actedAt desc. Used both for the "previously dismissed"
    // marker on freshly analyzed suggestions and for the read-only
    // dismissed-history view -- callers filter by status client-side.
    getSiteSuggestionStates: builder.query<
      ApiResponse<AiSuggestionState[]>,
      string
    >({
      query: (siteId) => ({
        url: `/ai/suggestions/site/${siteId}`,
        method: "GET",
      }),
      providesTags: (_result, _error, siteId) => [
        { type: "AI_SUGGESTION_STATE", id: siteId },
      ],
    }),
  }),
})

export const {
  useDismissSuggestionMutation,
  useMarkSuggestionImportedMutation,
  useGetSiteSuggestionStatesQuery,
  useLazyGetSiteSuggestionStatesQuery,
} = aiSuggestionsApi
